// --- Clinic time formatting (presentation layer only; DB stores HH:mm) ---
const CLINIC_TIMEZONE = 'Asia/Karachi';

function parseClinicTime(raw) {
  if (raw == null || raw === '') return null;
  const s = String(raw).trim().replace(/\s+/g, ' ');
  const zone = CLINIC_TIMEZONE;
  const formats = ['HH:mm', 'H:mm', 'HH:mm:ss', 'H:mm:ss', 'h:mm a', 'h:mma', 'hh:mm a', 'hh:mma', 'h a', 'ha', 'h:mm:ss a'];
  for (const fmt of formats) {
    const dt = DateTime.fromFormat(s, fmt, { zone, locale: 'en' });
    if (dt.isValid) return dt;
  }
  const iso = DateTime.fromISO(s, { zone });
  if (iso.isValid && /T|\d:\d/.test(s)) return iso;
  return null;
}

function toStoredTime(raw) {
  const dt = parseClinicTime(raw);
  return dt ? dt.toFormat('HH:mm') : null;
}

function formatTime12h(raw) {
  const dt = parseClinicTime(raw);
  if (!dt) return raw;
  return dt.setLocale('en-US').toFormat('h:mm a').replace(/\b(am|pm)\b/gi, (m) => m.toUpperCase());
}

function clinicNow() {
  return DateTime.now().setZone(CLINIC_TIMEZONE);
}

function formatDateDisplay(isoOrDate) {
  const raw = String(isoOrDate || '').trim();
  const datePart = raw.includes('T') ? raw.split('T')[0] : raw.slice(0, 10);
  const dt = DateTime.fromISO(datePart, { zone: CLINIC_TIMEZONE });
  return dt.isValid ? dt.toFormat('MMMM d, yyyy') : raw;
}
// --- end clinic time formatting ---


function rowsFrom(nodeName) {
  const items = $(nodeName).all();
  const out = [];
  for (const item of items) {
    const j = item.json;
    if (Array.isArray(j)) {
      for (const row of j) out.push(row);
    } else if (j && typeof j === 'object') {
      // empty object / error body without id fields
      if (j.doctor_id || j.appointment_id || j.clinic_id) out.push(j);
      else if (Array.isArray(j.body)) {
        for (const row of j.body) out.push(row);
      }
    }
  }
  return out;
}

const doctorRows = rowsFrom('Get Doctor');
const doctor = doctorRows[0] || null;
const trigger = $('Execute Workflow Trigger').first().json;

if (!doctor || !doctor.doctor_id) {
  return [{ json: { canBook: false, message: 'No doctor found with ID ' + trigger.doctor_id + '. Please check the doctor ID and try again.' } }];
}

const doctorLabel = doctor.doctor_name;
const workingDays = (doctor.working_days || '').split(',').map(d => d.trim()).filter(Boolean);
const dt = DateTime.fromISO(trigger.appointment_date, { zone: CLINIC_TIMEZONE });
if (!dt.isValid) {
  return [{ json: { canBook: false, message: 'The date ' + trigger.appointment_date + ' is not valid. Please use YYYY-MM-DD format.' } }];
}
const today = clinicNow().startOf('day');
if (dt.startOf('day') < today) {
  const todayDisplay = formatDateDisplay(today.toISODate());
  return [{ json: { canBook: false, message: 'Appointments cannot be booked for past dates. Today is ' + todayDisplay + '. Please choose today or a future date.' } }];
}
const weekdayMap = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const weekdayName = weekdayMap[dt.weekday - 1];
if (!workingDays.includes(weekdayName)) {
  return [{ json: { canBook: false, message: doctorLabel + ' does not work on ' + weekdayName + '. Working days are: ' + workingDays.join(', ') + '.' } }];
}

const appointmentTime = toStoredTime(trigger.appointment_time);
if (!appointmentTime) {
  return [{ json: { canBook: false, message: 'The time ' + trigger.appointment_time + ' is not valid. Please choose a slot from the available list.' } }];
}

const [startStr, endStr] = (doctor.working_hours || '09:00-17:00').split('-');
const duration = doctor.slot_duration_minutes || 30;
let slotCursor = DateTime.fromFormat(startStr.trim(), 'HH:mm', { zone: CLINIC_TIMEZONE });
const end = DateTime.fromFormat(endStr.trim(), 'HH:mm', { zone: CLINIC_TIMEZONE });
const allSlots = [];
while (slotCursor.isValid && end.isValid && slotCursor < end) {
  allSlots.push(slotCursor.toFormat('HH:mm'));
  slotCursor = slotCursor.plus({ minutes: duration });
}
if (!allSlots.includes(appointmentTime)) {
  return [{ json: { canBook: false, message: formatTime12h(appointmentTime) + ' is not a valid slot for ' + doctorLabel + '. Please choose an available time from CheckDoctorAvailability.' } }];
}

const conflictItems = rowsFrom('Get Conflicting Appointment').filter(i => i.appointment_id && toStoredTime(i.appointment_time) === appointmentTime).map(i => ({ json: i }));
if (conflictItems.length > 0) {
  const dateDisplay = formatDateDisplay(trigger.appointment_date);
  return [{ json: { canBook: false, message: 'Sorry, ' + doctorLabel + ' is already booked at ' + formatTime12h(appointmentTime) + ' on ' + dateDisplay + '. Please choose another slot.' } }];
}

const appointmentId = 'APT-' + Date.now().toString().slice(-8);
return [{ json: {
  canBook: true,
  appointment_id: appointmentId,
  doctor_id: trigger.doctor_id,
  doctor_name: doctorLabel,
  patient_name: trigger.patient_name,
  phone_number: trigger.phone_number,
  appointment_date: trigger.appointment_date,
  appointment_time: appointmentTime,
  appointment_date_display: formatDateDisplay(trigger.appointment_date),
  appointment_time_display: formatTime12h(appointmentTime),
  timezone: CLINIC_TIMEZONE,
  clinic_id: 'CLINIC-SMILECARE'
} }];

const v = $('Validate Booking').first().json;
const raw = $input.first().json;

function slotTakenMessage() {
  return (
    'Sorry, ' +
    v.doctor_name +
    ' is already booked at ' +
    v.appointment_time_display +
    ' on ' +
    v.appointment_date_display +
    '. Please choose another slot.'
  );
}

function genericFail() {
  return 'Could not save the appointment. Please try again in a moment.';
}

function looksLikePostgrestError(j) {
  if (!j || typeof j !== 'object' || Array.isArray(j)) return false;
  return Boolean(j.code || j.hint !== undefined || j.details !== undefined || (j.message && !j.appointment_id));
}

let body = raw;
if (raw && typeof raw === 'object' && raw.error && typeof raw.error === 'object') {
  body = raw.error;
}

if (Array.isArray(body)) {
  const row = body[0];
  if (row && row.appointment_id) {
    return [{ json: { insertOk: true } }];
  }
  return [{ json: { insertOk: false, message: genericFail() } }];
}

if (body && body.appointment_id && !looksLikePostgrestError(body)) {
  return [{ json: { insertOk: true } }];
}

if (looksLikePostgrestError(body)) {
  const code = String(body.code || '');
  const msg = String(body.message || '');
  if (code === '23505' || /duplicate|unique|conflict/i.test(msg)) {
    return [{ json: { insertOk: false, message: slotTakenMessage() } }];
  }
  return [{ json: { insertOk: false, message: genericFail() } }];
}

return [{ json: { insertOk: false, message: genericFail() } }];

